$ErrorActionPreference='Stop';$roots=@('backend/src/Compliance','backend/src/CompliancePlatform','docs/specs/compliance-readiness');$patterns=@('BEGIN PRIVATE KEY','BEGIN RSA PRIVATE KEY','BEGIN OPENSSH PRIVATE KEY','github_pat_','ghp_','COMPLIANCE_API_KEY=','AML_PROVIDER_SECRET=','KYC_PROVIDER_SECRET=','SCREENING_PROVIDER_SECRET=','REGULATOR_API_KEY=');$findings=@()
foreach($root in $roots){if(!(Test-Path $root)){throw "Required compliance path missing: $root"};Get-ChildItem $root -Recurse -File|Where-Object{$_.FullName -notmatch '\\(bin|obj)\\'}|ForEach-Object{foreach($pattern in $patterns){if(Select-String -Path $_.FullName -Pattern $pattern -SimpleMatch -ErrorAction SilentlyContinue){$findings+="$($_.FullName) -> $pattern"}}}}
if($findings){Write-Host 'Compliance secret scan FAIL';$findings|ForEach-Object{Write-Host $_};exit 1};Write-Host 'Compliance secret scan PASS'